{"cards": [{"node_code": "N_f9f404eaec01308b", "definition": "研究造船用材料力学、物理及化学性能的测试方法、标准规范、试验设备原理及数据处理技术，旨在验证材料质量与适用性。", "boundary": "本节点聚焦于“试验方法”与“检测技术”。边界在于区分“试验”与“材料性能本身”（如钢材强度数据归金属材料，试验过程归本节点）、“试验”与“结构设计”（基于试验结果的设计归船舶结构）。若内容涉及试验设备的研发制造，侧重设备工程可关联相关机械节点，侧重试验规程归本节点。", "includes": ["船用材料拉伸、冲击、疲劳等力学性能试验方法", "材料金相分析、腐蚀试验、无损检测技术", "材料试验标准、规范及试验数据处理与评估"], "excludes": ["具体材料（如钢材、塑料）的成分、微观组织及固有性能描述", "基于材料性能数据的船体结构强度计算与设计", "材料在船厂加工过程中的工艺参数监控"], "sibling_distinctions": [{"other_code": "N_760eb22878126281", "rule": "金属材料侧重材料本身的属性、分类及性能指标；材料试验侧重获取这些指标的测试手段、流程及标准。"}, {"other_code": "N_830a5cc98ca02765", "rule": "非金属材料侧重非金属类材料的属性；材料试验涵盖所有类型材料的通用或专用测试方法。"}, {"other_code": "N_4e26cb0d8261284c", "rule": "工程塑料侧重塑料类材料的具体应用与特性；材料试验侧重针对这些材料的测试规程。"}, {"other_code": "N_6b6d4939756d0581", "rule": "组合材料侧重复合材料的具体结构与性能；材料试验侧重针对复合材料的界面、层间等专项测试方法。"}], "cross_boundary_rule": "若内容涉及“试验设备的设计与制造”，主挂载本节点（侧重试验功能）；若侧重设备通用机械原理，可关联机械工程。若涉及“试验结果在结构设计中的应用”，主挂载船舶结构，本节点仅作为数据来源背景。"}, {"node_code": "N_760eb22878126281", "definition": "研究用于船舶建造与修理的各类金属材料，包括船用钢、铝合金、铜合金、钛合金等的成分、组织、性能、分类及选材原则。", "boundary": "本节点聚焦于“金属材料”这一特定类别。边界在于区分“金属”与“非金属”（如玻璃钢归非金属材料）、“金属”与“组合材料”（如金属基复合材料归组合材料）。若内容涉及金属材料的焊接工艺，侧重工艺归船舶建造工艺，侧重材料焊接性归本节点。", "includes": ["船用结构钢、高强度钢、耐候钢的成分与性能", "船用铝合金、镁合金、钛合金等轻金属及特种合金", "金属材料的腐蚀机理、防护材料及选材标准"], "excludes": ["非金属无机材料（如陶瓷、玻璃）及有机高分子材料（归非金属材料或工程塑料）", "由金属与其他材料复合而成的组合材料（归组合材料）", "金属材料的焊接、切割、成型等具体加工工艺（归船舶建造工艺）"], "sibling_distinctions": [{"other_code": "N_830a5cc98ca02765", "rule": "金属材料以金属元素为主；非金属材料以非金属元素（如碳、硅、氧）为主，如玻璃钢、橡胶。"}, {"other_code": "N_4e26cb0d8261284c", "rule": "工程塑料属于高分子材料，归入非金属材料大类下的细分或独立节点，与金属材料在化学组成上截然不同。"}, {"other_code": "N_6b6d4939756d0581", "rule": "组合材料强调两种或多种不同材料的复合结构（如金属-非金属），而金属材料侧重单一金属或合金体系。"}, {"other_code": "N_f9f404eaec01308b", "rule": "金属材料侧重材料本身的属性与分类；材料试验侧重测试这些属性的方法。"}], "cross_boundary_rule": "若内容涉及“金属基复合材料”，主挂载组合材料；若侧重金属基体本身的性能，可关联本节点。若涉及“金属材料的焊接工艺”，主挂载船舶建造工艺，本节点仅涉及材料焊接性基础。"}, {"node_code": "N_830a5cc98ca02765", "definition": "研究用于船舶建造与修理的非金属无机及有机材料，包括玻璃钢、橡胶、陶瓷、玻璃、木材及工程塑料等的性能、应用及选材。", "boundary": "本节点聚焦于“非金属材料”。边界在于区分“非金属”与“金属”（归金属材料）、“非金属”与“组合材料”（归组合材料）。注意：树中另有“工程塑料”节点，若工程塑料内容独立且详细，应优先归入“工程塑料”节点；本节点主要涵盖除工程塑料外的其他非金属材料，或作为工程塑料的上级概念（视具体数据粒度，若工程塑料为独立兄弟节点，本节点应排除纯工程塑料内容，或仅涵盖其基础共性）。鉴于兄弟节点中有“工程塑料”，本节点应侧重玻璃钢、橡胶、陶瓷、木材等。", "includes": ["船用玻璃钢（FRP）的基体树脂、增强纤维及成型性能", "船用橡胶、密封材料、绝缘材料的性能与应用", "船用陶瓷、玻璃、木材等非金属材料特性"], "excludes": ["各类金属及合金材料（归金属材料）", "由金属与非金属复合而成的组合材料（归组合材料）", "纯工程塑料的详细分类与改性（若“工程塑料”节点存在，优先归入该节点）"], "sibling_distinctions": [{"other_code": "N_760eb22878126281", "rule": "非金属材料以非金属元素为主；金属材料以金属元素为主。"}, {"other_code": "N_4e26cb0d8261284c", "rule": "工程塑料是高分子材料的一种，若树中单独列出，本节点应排除纯工程塑料内容，或仅涵盖其作为非金属材料的基础共性；具体塑料品种归工程塑料节点。"}, {"other_code": "N_6b6d4939756d0581", "rule": "组合材料强调复合结构；非金属材料侧重单一非金属体系（如纯玻璃钢、纯橡胶）。"}, {"other_code": "N_f9f404eaec01308b", "rule": "非金属材料侧重材料属性；材料试验侧重测试方法。"}], "cross_boundary_rule": "若内容涉及“玻璃钢”，归入本节点（因玻璃钢常被视为典型的船用非金属材料，且树中无单独玻璃钢节点）。若内容涉及“工程塑料”，优先归入“工程塑料”节点。若涉及“非金属基复合材料”，归入组合材料。"}]}
